const rows = $input.all().map(i => i.json).map(r => ({
  ...r,
  open: parseFloat(r.open),
  high: parseFloat(r.high),
  low: parseFloat(r.low),
  close: parseFloat(r.close),
  open_time: new Date(r.open_time)
})).sort((a, b) => a.open_time - b.open_time);

const symbols = [...new Set(rows.map(r => r.symbol))];
const allTrades = [];

function ema(values, period) {
  const k = 2 / (period + 1);
  const out = [];
  let prev = null;
  for (let i = 0; i < values.length; i++) {
    if (i < period - 1) { out.push(null); continue; }
    if (prev === null) {
      const seed = values.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0) / period;
      prev = seed; out.push(seed); continue;
    }
    prev = values[i] * k + prev * (1 - k);
    out.push(prev);
  }
  return out;
}

function atr(candles, period) {
  const trs = [];
  for (let i = 0; i < candles.length; i++) {
    if (i === 0) { trs.push(candles[i].high - candles[i].low); continue; }
    const prevClose = candles[i - 1].close;
    const tr = Math.max(
      candles[i].high - candles[i].low,
      Math.abs(candles[i].high - prevClose),
      Math.abs(candles[i].low - prevClose)
    );
    trs.push(tr);
  }
  const out = [];
  for (let i = 0; i < trs.length; i++) {
    if (i < period - 1) { out.push(null); continue; }
    const avg = trs.slice(i - period + 1, i + 1).reduce((a, b) => a + b, 0) / period;
    out.push(avg);
  }
  return out;
}

function swingLow(candles, idx, lookback) {
  const start = Math.max(0, idx - lookback);
  const slice = candles.slice(start, idx + 1);
  return Math.min(...slice.map(c => c.low));
}
function swingHigh(candles, idx, lookback) {
  const start = Math.max(0, idx - lookback);
  const slice = candles.slice(start, idx + 1);
  return Math.max(...slice.map(c => c.high));
}

for (const symbol of symbols) {
  const candles = rows.filter(r => r.symbol === symbol);
  if (candles.length < 30) continue;

  const closes = candles.map(c => c.close);
  const ema9 = ema(closes, 9);
  const ema21 = ema(closes, 21);
  const atr14 = atr(candles, 14);

  let position = null; // { direction, entry_price, sl1, sl2, tp1, tp2, entry_time, entry_idx }

  for (let i = 22; i < candles.length; i++) {
    const c = candles[i];

    // Neu dang co lenh mo, kiem tra co cham TP/SL chua
    if (position) {
      const hitTP2 = position.direction === 'BUY' ? c.high >= position.tp2 : c.low <= position.tp2;
      const hitTP1 = position.direction === 'BUY' ? c.high >= position.tp1 : c.low <= position.tp1;
      const hitSL1 = position.direction === 'BUY' ? c.low <= position.sl1 : c.high >= position.sl1;
      const hitSL2 = position.direction === 'BUY' ? c.low <= position.sl2 : c.high >= position.sl2;

      let outcome = null, exitPrice = null;
      if (hitSL2) { outcome = 'SL2_HIT'; exitPrice = position.sl2; }
      else if (hitSL1) { outcome = 'SL1_HIT'; exitPrice = position.sl1; }
      else if (hitTP2) { outcome = 'TP2_HIT'; exitPrice = position.tp2; }
      else if (hitTP1) { outcome = 'TP1_HIT'; exitPrice = position.tp1; }

      if (outcome) {
        const risk = Math.abs(position.entry_price - position.sl1);
        const reward = position.direction === 'BUY'
          ? (exitPrice - position.entry_price)
          : (position.entry_price - exitPrice);
        const rr = risk > 0 ? (reward / risk) : 0;
        allTrades.push({
          symbol, timeframe: candles[0].timeframe, direction: position.direction,
          entry_time: position.entry_time.toISOString(), entry_price: position.entry_price,
          sl1: position.sl1, sl2: position.sl2, tp1: position.tp1, tp2: position.tp2,
          outcome, exit_time: c.open_time.toISOString(), exit_price: exitPrice, rr_achieved: rr
        });
        position = null;
      }
      continue; // dang co lenh, khong mo lenh moi cung luc
    }

    // Kiem tra tin hieu giao cat EMA de mo lenh moi
    if (ema9[i - 1] === null || ema21[i - 1] === null || ema9[i] === null || ema21[i] === null || atr14[i] === null) continue;

    const crossUp = ema9[i - 1] <= ema21[i - 1] && ema9[i] > ema21[i];
    const crossDown = ema9[i - 1] >= ema21[i - 1] && ema9[i] < ema21[i];

    if (crossUp) {
      const entry = c.close;
      const sr = swingLow(candles, i, 20);
      const sl1 = sr - atr14[i];
      const sl2 = sr - atr14[i] * 1.5;
      const risk = entry - sl1;
      position = {
        direction: 'BUY', entry_price: entry, entry_time: c.open_time,
        sl1, sl2, tp1: entry + risk * 1, tp2: entry + risk * 2
      };
    } else if (crossDown) {
      const entry = c.close;
      const sr = swingHigh(candles, i, 20);
      const sl1 = sr + atr14[i];
      const sl2 = sr + atr14[i] * 1.5;
      const risk = sl1 - entry;
      position = {
        direction: 'SELL', entry_price: entry, entry_time: c.open_time,
        sl1, sl2, tp1: entry - risk * 1, tp2: entry - risk * 2
      };
    }
  }
  // Lenh con mo cuoi giai doan backtest thi bo qua (khong tinh vao thang/thua)
}

return allTrades.map(t => ({ json: t }));

const trades = $input.all().map(i => i.json);
const symbols = [...new Set(trades.map(t => t.symbol))];
const summaries = [];

for (const symbol of symbols) {
  const sTrades = trades.filter(t => t.symbol === symbol);
  const wins = sTrades.filter(t => t.outcome === 'TP1_HIT' || t.outcome === 'TP2_HIT').length;
  const losses = sTrades.filter(t => t.outcome === 'SL1_HIT' || t.outcome === 'SL2_HIT').length;
  const total = sTrades.length;
  const avgRR = total > 0 ? (sTrades.reduce((a, t) => a + (t.rr_achieved || 0), 0) / total) : 0;
  const times = sTrades.map(t => new Date(t.entry_time).getTime());
  summaries.push({
    symbol,
    timeframe: sTrades[0] ? sTrades[0].timeframe : null,
    total_trades: total,
    wins, losses, open_trades: 0,
    win_rate_pct: total > 0 ? ((wins / total) * 100) : 0,
    avg_rr_achieved: avgRR,
    period_start: times.length ? new Date(Math.min(...times)).toISOString() : null,
    period_end: times.length ? new Date(Math.max(...times)).toISOString() : null
  });
}

return summaries.map(s => ({ json: s }));
